27	function getTraceOrThrow(params: AssertionParams) {
28	  const trace = params.assertionValueContext.trace;
29	  if (!trace || !trace.spans) {
30	    throw new Error(`No trace data available for ${params.baseType} assertion`);
31	  }
32	  return trace;
33	}
