43	function requireNamedTrajectoryMatcher(
44	  matcher: TrajectoryStepMatcher,
45	  assertionType: string,
46	  index?: number,
47	) {
48	  if (matcher.pattern || matcher.name) {
49	    return;
50	  }
51	
52	  const stepLabel = index === undefined ? 'object' : `step ${index + 1}`;
53	  throw new Error(
54	    `${assertionType} assertion ${stepLabel} must include a name or pattern property`,
55	  );
56	}
