122	export const handleTrajectoryToolUsed = (params: AssertionParams): GradingResult => {
123	  const trace = getTraceOrThrow(params);
124	  const steps = extractTrajectorySteps(trace).filter((step) => step.type === 'tool');
125	  const expected = resolveToolMatchers(params.renderedValue ?? params.assertion.value);
126	
127	  if (expected.kind === 'list') {
128	    if (expected.matchers.length === 0) {
129	      throw new Error('trajectory:tool-used assertion requires at least one expected tool');
130	    }
131	
132	    const missing = expected.matchers.filter(
133	      (matcher) => !steps.some((step) => matchesTrajectoryStep(step, matcher)),
134	    );
135	    const matched = expected.matchers.filter((matcher) =>
136	      steps.some((step) => matchesTrajectoryStep(step, matcher)),
137	    );
138	
139	    const pass = params.inverse ? matched.length === 0 : missing.length === 0;
140	    const actualTools = steps.map(formatTrajectoryStep);
141	
142	    const expectedTools = expected.matchers.map(
143	      (matcher) => matcher.pattern || matcher.name || '*',
144	    );
145	
146	    let reason: string;
147	    if (params.inverse) {
148	      reason = pass
149	        ? `Forbidden tool(s) were not used: ${expectedTools.join(', ')}`
150	        : `Forbidden tool(s) were used: ${matched
151	            .map((matcher) => matcher.pattern || matcher.name || '*')
152	            .join(', ')}. Actual tools: ${formatStepList(actualTools)}`;
153	    } else if (pass) {
154	      reason = `Observed required tool(s): ${expectedTools.join(', ')}. Actual tools: ${formatStepList(actualTools)}`;
155	    } else {
156	      const missingTools = missing.map((matcher) => matcher.pattern || matcher.name || '*');
157	      reason = `Missing required tool(s): ${missingTools.join(', ')}. Actual tools: ${formatStepList(actualTools)}`;
158	    }
159	
160	    return {
161	      pass,
162	      score: pass ? 1 : 0,
163	      reason,
164	      assertion: params.assertion,
165	    };
166	  }
167	
168	  const matcher = expected.matcher;
169	  const min = matcher.min ?? 1;
170	  const max = matcher.max;
171	  if (!matcher.pattern && !matcher.name) {
172	    throw new Error(
173	      'trajectory:tool-used assertion object must include a name or pattern property',
174	    );
175	  }
176	
177	  const matchingSteps = steps.filter((step) => matchesTrajectoryStep(step, matcher));
178	  const count = matchingSteps.length;
179	  const basePass = count >= min && (max === undefined || count <= max);
180	  const pass = applyInverse(basePass, params.inverse);
181	  const matcherLabel = matcher.pattern || matcher.name || '*';
182	
183	  let reason = `Matched tool "${matcherLabel}" ${count} time(s)`;
184	  if (max !== undefined) {
185	    reason += ` (expected ${min}-${max})`;
186	  } else {
187	    reason += ` (expected at least ${min})`;
188	  }
189	  if (matchingSteps.length > 0) {
190	    reason += `. Matches: ${matchingSteps.map(formatTrajectoryStep).join(', ')}`;
191	  }
192	
193	  if (params.inverse) {
194	    reason = basePass
195	      ? `Tool "${matcherLabel}" matched ${count} time(s), which violates the inverse assertion`
196	      : `Tool "${matcherLabel}" did not satisfy the forbidden match condition`;
197	  }
198	
199	  return {
200	    pass,
201	    score: pass ? 1 : 0,
202	    reason,
203	    assertion: params.assertion,
204	  };
205	};
