5	export type TrajectoryStepType = 'command' | 'message' | 'reasoning' | 'search' | 'span' | 'tool';
6	type TrajectoryAttributes = Record<string, unknown>;
7	
8	export interface TrajectoryStepMatcher {
9	  name?: string;
10	  pattern?: string;
11	  type?: TrajectoryStepType | TrajectoryStepType[];
12	}
13	
14	export interface TrajectoryStep {
15	  aliases: string[];
16	  attributes: TrajectoryAttributes;
17	  endTime?: number;
18	  name: string;
19	  spanId: string;
20	  spanName: string;
21	  startTime: number;
22	  statusCode?: number;
23	  statusMessage?: string;
24	  type: TrajectoryStepType;
25	}
26	
27	const TOOL_ATTRIBUTE_KEYS = [
28	  'tool.name',
29	  'tool_name',
30	  'tool',
31	  'function.name',
32	  'function_name',
33	  'gen_ai.tool.name',
34	  'codex.mcp.tool',
35	  'agent.tool',
36	  'agent.tool_name',
37	  'agent.toolName',
38	] as const;
39	
40	const COMMAND_ATTRIBUTE_KEYS = [
41	  'codex.command',
42	  'command',
43	  'command.name',
44	  'command_name',
45	] as const;
46	
47	const SEARCH_ATTRIBUTE_KEYS = ['codex.search.query', 'search.query', 'search_query'] as const;
48	
49	const GENERIC_QUERY_ATTRIBUTE_KEYS = ['query'] as const;
50	
51	const SEARCH_SPAN_NAME_PATTERN = /(^|[\s._:/-])(search|find|lookup|retriev(?:e|al))($|[\s._:/-])/i;
52	
53	const MAX_JUDGE_SUMMARY_STEPS = 24;
54	const JUDGE_SUMMARY_HEAD_STEPS = 12;
55	const JUDGE_SUMMARY_TAIL_STEPS = 12;
56	
57	interface TrajectoryStepStatus {
58	  code: number;
59	  message?: string;
60	}
61	
62	interface JudgeTrajectoryStep {
63	  collapsedCount?: number;
64	  index: number;
65	  name: string;
66	  spanName?: string;
67	  status?: TrajectoryStepStatus;
