75	function getStringAttribute(
76	  attributes: TrajectoryAttributes,
77	  keys: readonly string[],
78	): string | undefined {
79	  for (const key of keys) {
80	    const value = attributes[key];
81	    if (typeof value === 'string' && value.trim()) {
82	      return value.trim();
83	    }
84	  }
85	  return undefined;
86	}
87	
88	function hasSameStatus(left?: TrajectoryStepStatus, right?: TrajectoryStepStatus): boolean {
89	  return left?.code === right?.code && left?.message === right?.message;
90	}
91	
92	function isSearchLikeSpan(span: TraceSpan): boolean {
93	  const attributes = span.attributes || {};
94	  if (SEARCH_SPAN_NAME_PATTERN.test(span.name) || span.name.startsWith('search ')) {
95	    return true;
96	  }
97	
98	  return Object.keys(attributes).some(
99	    (key) => key !== 'query' && /(^|[._])(search|lookup|retriev(?:e|al))($|[._])/i.test(key),
100	  );
101	}
102	
103	function getTrajectoryStepStatus(step: Pick<TrajectoryStep, 'statusCode' | 'statusMessage'>) {
104	  if (step.statusCode === undefined || step.statusCode === 0) {
105	    return undefined;
106	  }
107	
108	  return {
109	    code: step.statusCode,
110	    ...(step.statusMessage ? { message: step.statusMessage } : {}),
111	  };
112	}
113	
114	function getCommandExecutable(command: string): string | undefined {
115	  const executable = command.trim().split(/\s+/)[0];
116	  return executable || undefined;
117	}
118	
119	function extractToolName(span: TraceSpan): string | undefined {
120	  const attributes = span.attributes || {};
121	
122	  const directMatch = getStringAttribute(attributes, TOOL_ATTRIBUTE_KEYS);
123	  if (directMatch) {
124	    return directMatch;
125	  }
126	
127	  for (const [key, value] of Object.entries(attributes)) {
128	    if (typeof value !== 'string' || !value.trim()) {
129	      continue;
130	    }
131	
132	    if (/tool.?name|function.?name/i.test(key)) {
133	      return value.trim();
134	    }
135	
136	    if (/(^|[._])tool($|[._])/i.test(key) && !/result|output/i.test(key)) {
137	      return value.trim();
138	    }
139	  }
140	
141	  if (span.name.startsWith('mcp ')) {
142	    const slashIndex = span.name.lastIndexOf('/');
143	    if (slashIndex !== -1 && slashIndex < span.name.length - 1) {
144	      return span.name.slice(slashIndex + 1).trim();
145	    }
146	  }
147	
148	  return undefined;
149	}
150	
151	function extractCommand(span: TraceSpan): string | undefined {
152	  const attributes = span.attributes || {};
153	
154	  const directMatch = getStringAttribute(attributes, COMMAND_ATTRIBUTE_KEYS);
155	  if (directMatch) {
156	    return directMatch;
157	  }
158	
159	  for (const [key, value] of Object.entries(attributes)) {
160	    if (typeof value !== 'string' || !value.trim()) {
161	      continue;
162	    }
163	
164	    if (/command/i.test(key) && !/output|result/i.test(key)) {
165	      return value.trim();
166	    }
167	  }
168	
169	  if (span.name.startsWith('exec ')) {
170	    return span.name.slice('exec '.length).trim();
171	  }
172	
173	  return undefined;
174	}
175	
176	function extractSearchQuery(span: TraceSpan): string | undefined {
177	  const attributes = span.attributes || {};
178	
179	  const directMatch = getStringAttribute(attributes, SEARCH_ATTRIBUTE_KEYS);
180	  if (directMatch) {
181	    return directMatch;
182	  }
183	
184	  const genericQuery = getStringAttribute(attributes, GENERIC_QUERY_ATTRIBUTE_KEYS);
185	  if (genericQuery && isSearchLikeSpan(span)) {
186	    return genericQuery;
187	  }
188	
189	  if (span.name.startsWith('search ')) {
190	    return span.name.slice('search '.length).replace(/^"|"$/g, '').trim();
191	  }
192	
193	  return undefined;
194	}
195	
196	function isReasoningSpan(span: TraceSpan): boolean {
197	  const attributes = span.attributes || {};
198	  if (attributes['codex.item.type'] === 'reasoning') {
199	    return true;
200	  }
201	
202	  return /^reasoning([_\s]|$)/i.test(span.name) || span.name === 'reasoning';
203	}
204	
205	function isMessageSpan(span: TraceSpan): boolean {
206	  const attributes = span.attributes || {};
207	  if (attributes['codex.item.type'] === 'agent_message') {
208	    return true;
209	  }
210	
211	  return span.name === 'agent response' || span.name === 'send input';
212	}
